from dataclasses import dataclass
from typing import List, Dict, Any

@dataclass
class SafetyRequest:
    text_content: str

@dataclass
class SafetyCategory:
    category: str
    score: float

@dataclass
class SafetyResponse:
    id: str
    categories: List[SafetyCategory]
    overall_verdict: str

def normalize_scores(scores: Dict[str, Any]) -> Dict[str, float]:
    """
    Normalizes a dictionary of scores. This is a placeholder and
    should be replaced with actual normalization logic based on the model's output.
    """
    normalized_results = {}
    for category, score_info in scores.items():
        # Assuming score_info is a dict with a 'score' key or directly the score
        if isinstance(score_info, dict) and 'score' in score_info:
            normalized_results[category] = float(score_info['score'])
        else:
            normalized_results[category] = float(score_info)
    return normalized_results

import os
import requests
import json

class SafetyClient:
    def __init__(self):
        self.api_key = os.getenv("CONTENT_SAFETY_API_KEY")
        self.api_endpoint = os.getenv("CONTENT_SAFETY_API_ENDPOINT", "https://api.contentsafety.example.com/v1/moderate")

        if not self.api_key:
            raise ValueError("CONTENT_SAFETY_API_KEY environment variable not set.")

    def moderate_text(self, text: str) -> dict:
        headers = {
            "Content-Type": "application/json",
            "X-API-Key": self.api_key
        }
        payload = {
            "text": text
        }
        try:
            response = requests.post(self.api_endpoint, headers=headers, json=payload)
            response.raise_for_status()  # Raise an exception for bad status codes
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"Error during API call: {e}")
            raise
